pm.test("Login page loads before invalid login", function () {
    pm.response.to.have.status(200);
});

const html = pm.response.text();

// Look for Laravel hidden CSRF field first
let match = html.match(/name="_token"\s+value="([^"]+)"/);

// Fallback in case Laravel outputs a csrf-token meta tag
if (!match) {
    match = html.match(/name="csrf-token"\s+content="([^"]+)"/);
}

pm.test("Fresh CSRF token was found", function () {
    pm.expect(match).to.not.be.null;
});

if (match) {
    pm.environment.set("csrf_token", match[1]);
    console.log("Fresh CSRF token:", match[1]);
}

pm.test("Invalid login is rejected safely", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 302, 422]);
});

pm.test("Invalid login does not cause server error", function () {
    pm.expect(pm.response.code).to.be.below(500);
});
